from typing import Any

import dspy
from dspy.utils.dummies import DummyLM


class SchemaAwareDummyLM(DummyLM):
    def __init__(self):
        super().__init__([{"payload": {"city": "Paris", "count": 1}}], adapter=dspy.JSONAdapter())
        self.model = "openai/gpt-4o-mini"

    @property
    def supported_params(self):
        return {"response_format"}

    @property
    def supports_response_schema(self):
        return True


class MappingSignature(dspy.Signature):
    question: str = dspy.InputField()
    payload: dict[str, Any] = dspy.OutputField()

lm = SchemaAwareDummyLM()
predict = dspy.Predict(MappingSignature)

with dspy.context(lm=lm, adapter=dspy.JSONAdapter()):
    result = predict(question="Where should I go?")

response_format = lm.history[0]["kwargs"]["response_format"]
assert response_format == {"type": "json_object"}
assert result.payload == {"city": "Paris", "count": 1}

print(response_format)
print(result.payload)
