import dspy
from dspy.utils.dummies import DummyLM


class ReasoningDummyLM(DummyLM):
    def __init__(self):
        super().__init__([{"answer": "Paris"}], reasoning=True, adapter=dspy.JSONAdapter())
        self.model = "anthropic/claude-3-7-sonnet-20250219"

    @property
    def supported_params(self):
        return {"response_format"}

    @property
    def supports_response_schema(self):
        return True

    @property
    def supports_reasoning(self):
        return True


class ReasonedAnswer(dspy.Signature):
    question: str = dspy.InputField()
    reasoning: dspy.Reasoning = dspy.OutputField()
    answer: str = dspy.OutputField()

lm = ReasoningDummyLM()
predict = dspy.Predict(ReasonedAnswer)

with dspy.context(lm=lm, adapter=dspy.JSONAdapter()):
    result = predict(question="What is the capital of France?")

system_prompt = lm.history[0]["messages"][0]["content"]
kwargs = lm.history[0]["kwargs"]

assert "[[ ## reasoning ## ]]" not in system_prompt
assert kwargs["reasoning_effort"] == "low"
assert str(result.reasoning) == "Some reasoning"
assert result.answer == "Paris"

print(system_prompt)
print({"reasoning_effort": kwargs["reasoning_effort"], "reasoning": str(result.reasoning), "answer": result.answer})
